1193			\ket{\hat{\psi}}_{\mathsf{A}\mathsf{A}'\mathsf{A}''\mathsf{B}\mathsf{B}'\mathsf{B}''}
1194			\,=\, (\ket{\psi})_{\mathsf{A}\mathsf{B}}
