605	\section{Formalization support for the robustness bound}
606	
607	The following monotonicity statement is not a named result of the source
608	article.  It records, as a single inequality, the adjustment of the universal
609	constants of Theorem~\ref{thm:pauli} that is used when the robustness bound is
610	passed from its squared to its unsquared form, and when several estimates are
611	brought to a common scale.
612	
613	\begin{lemma}[Monotonicity of the robustness bound in its universal constants]\label{lem:delta-qld-mono-support}
614		\lean{MIPStarRE.QPBT.deltaQld_mono}
615		\leanok
616		\uses{thm:pauli}
617		Write $\delta_{\mathrm{qld}}^{a,b}(\eps,m,d,q) = a(md)^a\bigl(\eps^b + q^{-b} + 2^{-bmd}\bigr)$ for the soundness function of Theorem~\ref{thm:pauli} with universal constants $a$ and $b$. Let $(q,m,d)$ be an admissible parameter tuple (Definition~\ref{def:admissible}), let $1 \le a \le a'$, let $0 < b' \le b$, and let $0 \le \eps \le 1$. Then
618		\[
619			\delta_{\mathrm{qld}}^{a,b}(\eps,m,d,q) \le \delta_{\mathrm{qld}}^{a',b'}(\eps,m,d,q)\;.
620		\]
621	\end{lemma}
622	\begin{proof}
623		\leanok
624		\uses{def:admissible}
625		Admissibility gives $md \ge 1$ and $q \ge 1$, so $a(md)^a \le a'(md)^{a'}$. In the bracket, $\eps^b \le \eps^{b'}$ because $0 \le \eps \le 1$ and $0 < b' \le b$; $q^{-b} \le q^{-b'}$ because $q \ge 1$ and $-b \le -b'$; and $2^{-bmd} \le 2^{-b'md}$ because $md \ge 0$ and $-bmd \le -b'md$. Both factors are nonnegative, so the two products compare factorwise.
626	\end{proof}
